const uid=i=>String(i.id);const categoryPhoto=category=>{const c=String(category||'').toLowerCase();if(/personal|bath|beauty|hygien/.test(c))return'item-personal-care.jpg';if(/clean|household|laundry/.test(c))return'item-cleaning.jpg';if(/meat|seafood|poultry|fish/.test(c))return'item-meat.jpg';if(/dairy|egg|milk|cheese/.test(c))return'item-dairy.jpg';if(/beverage|drink|juice/.test(c))return'item-beverages.jpg';if(/frozen|freezer/.test(c))return'frozen-peas.png';if(/produce|fruit|vegetab/.test(c))return'item-produce.jpg';return'item-pantry.jpg'};
const productPhoto=(name,brand)=>{const n=String(name||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim(),b=String(brand||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();if(/barilla/.test(b)&&/penne/.test(n))return'barilla-penne.jpg';if(/bob.?s red mill/.test(b)&&/oat/.test(n))return'bobs-red-mill-rolled-oats.jpg';if(/hunt/.test(b)&&/tomato/.test(n))return'hunts-crushed-tomatoes.jpg';if(/goya/.test(b)&&/black bean/.test(n))return'goya-black-beans.jpg';if(/organic valley/.test(b)&&/whole milk/.test(n))return'organic-valley-whole-milk.jpg';if(/tillamook/.test(b)&&/cheddar/.test(n))return'tillamook-cheddar.jpg';if(/california olive ranch/.test(b)&&/olive oil/.test(n))return'california-olive-ranch-oil.jpg';if(/green giant/.test(b)&&/pea/.test(n))return'frozen-peas.png';if(/dawn/.test(b)&&/soap/.test(n))return'dish-soap.png';if(/baby spinach/.test(n))return'baby-spinach.jpg';if(/store brand/.test(b)&&/chicken breast/.test(n))return'chicken-breast-real.jpg';return''};
