async function api(path,method='GET',data){const r=await fetch('/api/'+path,{method,cache:'no-store',headers:{...(data?{'Content-Type':'application/json'}:{}),...(method!=='GET'?{'X-CSRF-Token':csrf}:{})},...(data?{body:JSON.stringify(data)}:{})});let d;try{d=await r.json()}catch{throw new Error('The server did not respond. Please try again.')}if(!r.ok){const error=new Error((d.error||'The request did not finish.')+(d.code?' ['+d.code+']':'')+(d.reference?' Reference '+d.reference:''));error.code=d.code;error.reference=d.reference;throw error;}return d}
